const express = require('express');
const app = express();
const mongoose = require('mongoose');

// IoT Device Schema
const deviceSchema = new mongoose.Schema({
  deviceId: String,
  name: String,
  firmware: String,
  status: String,
  isAdmin: { type: Boolean, default: false },
  allowOTA: { type: Boolean, default: false },
  debugMode: { type: Boolean, default: false },
  webhookUrl: String,
  displayWidget: String, // HTML widget rendered on dashboard
  lastSeen: Date,
  telemetry: Object
});

const Device = mongoose.model('Device', deviceSchema);

app.use(express.json());

// Middleware to set various headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  next();
});

// IoT device message ingestion endpoint
// Devices POST telemetry and status updates
app.post('/api/v2/devices/:deviceId/messages', async (req, res) => {
  try {
    const { deviceId } = req.params;
    const device = await Device.findOne({ deviceId });

    if (!device) {
      return res.status(404).json({ error: 'Device not found' });
    }

    // Mass assignment: directly spread request body into device update
    // Intended for telemetry fields but accepts ANY field
    const updatePayload = {
      lastSeen: new Date(),
      ...req.body
    };

    await Device.findOneAndUpdate(
      { deviceId },
      { $set: updatePayload },
      { new: true }
    );

    res.json({ status: 'accepted', deviceId });
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

// Dashboard endpoint - renders device widget HTML
app.get('/dashboard/device/:deviceId', async (req, res) => {
  const device = await Device.findOne({ deviceId: req.params.deviceId });
  if (!device) return res.status(404).send('Not found');

  // Renders the displayWidget field directly into HTML
  const html = `
    <!DOCTYPE html>
    <html>
    <head><title>${device.name} - Dashboard</title></head>
    <body>
      <h1>Device: ${device.name}</h1>
      <div class="widget-container">
        ${device.displayWidget || '<p>No widget configured</p>'}
      </div>
      <script src="/static/dashboard.js"></script>
    </body>
    </html>
  `;
  res.send(html);
});

// Admin panel - checks isAdmin flag on device for special operations
app.post('/api/v2/devices/:deviceId/ota', async (req, res) => {
  const device = await Device.findOne({ deviceId: req.params.deviceId });
  if (!device) return res.status(404).json({ error: 'Not found' });

  if (!device.allowOTA) {
    return res.status(403).json({ error: 'OTA not permitted for this device' });
  }

  // Trigger firmware update
  res.json({ status: 'OTA initiated', firmware: req.body.firmwareUrl });
});

app.listen(3000, () => console.log('IoT Gateway running on :3000'));
